type Rule struct{ Match string; Dest Handler }
type RoutingTable struct { rules map[string]Handler; fallback Handler }
var live atomic.Pointer[RoutingTable]           // Go 1.19+

func route(key string, m Message) {
	t := live.Load()                            // one snapshot per message
	if h, ok := t.rules[key]; ok { h.Handle(m); return }
	t.fallback.Handle(m)                        // unmatched goes somewhere visible
}
func publish(t *RoutingTable) { live.Store(t) } // control channel

